L["%s is on your bars where %s keeps it."] = "%s(은)는 %s 위치의 단축바에 있습니다."
L["%s is ready for %s%s|r. %s%s. Open %s for a waypoint."] = "%s, %s%s|r 준비됨. %s%s. 경유지는 %s(을)를 여세요."
L["%s is switched off. Turn it on under Settings > Modules."] = "%s(이)가 꺼져 있습니다. 설정 > 모듈에서 켜세요."
L["%s is the yardstick: every other stat is weighed against it."] = "%s(이)가 기준입니다: 다른 모든 능력치는 이것과 비교합니다."
L["%s is turned off, so its settings are hidden. Turn it on under Modules below."] = "%s(이)가 꺼져 있어 설정이 숨겨졌습니다. 아래 모듈에서 켜세요."
