L["/nf trainer: a waypoint to your nearest class trainer"] = "/nf trainer: 가장 가까운 직업 전문가로 가는 경유지"
L["/nf xp start, pause or reset: the XP ticker"] = "/nf xp start, pause 또는 reset: 경험치 기록기"
