L["/nfquests (or /nfcompleto): the Quest List, in Discovery"] = "/nfquests (또는 /nfcompleto): 발견의 퀘스트 목록"
L["0 keeps it up until you close it."] = "0이면 닫을 때까지 유지됩니다."
