L["Added %d consumables to the Consumable Bar."] = "소비용품 %d개를 소비용품 바에 추가했습니다."
L["Added %d consumables; %d were already listed or past the %d limit."] = "소비용품 %d개 추가함. %d개는 이미 목록에 있거나 한도 %d개를 넘었습니다."
