L["Also a grey star on the map for the rares you have killed."] = "처치한 희귀 몬스터도 지도에 회색 별로 표시합니다."
L["Also hidden for a few seconds after you dismount, while the pet comes back."] = "탈것에서 내린 후 소환수가 돌아오는 몇 초 동안도 숨깁니다."
