L["Also keeps your last whispers and group chat lines with each player."] = "각 플레이어와의 마지막 귓속말과 파티 대화도 보관합니다."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "경유지 위치에 세계 지도도 열어 어디인지 보여줍니다. 전투 중이 아닐 때만."
L["Also prints the summary when you leave a raid."] = "공격대를 떠날 때도 요약을 출력합니다."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "인스턴스 안에서도 알립니다. 약초나 광석이 있는 곳이 드물어 기본값은 꺼짐입니다."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "목록의 각 제조법 줄 오른쪽에 이익을 초록색 또는 빨간색으로 표시합니다. 이익을 모르는 제조법은 표시하지 않습니다."
L["Also thanks players in your party or raid."] = "파티나 공격대의 플레이어에게도 감사를 표합니다."
L["Also used inside dungeons and raids."] = "던전과 공격대 안에서도 사용합니다."
L["Also warns about rares you have killed before."] = "이전에 처치한 희귀 몬스터도 경고합니다."
L["Also warns while your pet is set to passive."] = "소환수가 수동 상태일 때도 경고합니다."
L["Also warns while your pet's health is under the threshold, in combat too."] = "소환수의 생명력이 기준 미만일 때도 경고합니다 (전투 중 포함)."
L["Also worth a look"] = "이것도 볼 만함"
