L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "\"소지품이 가득 찼습니다\" 오류가 나면 위 기준보다 빈 칸이 많아도 20초간 줄을 표시합니다."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "이름과 내용 또는 내용만으로 같은 매크로를 이미 가진 부캐릭터는 자신의 것을 사용합니다."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "우편함 보내기 탭 옆의 부캐릭터 버튼이 이 서버와 진영의 캐릭터를 레벨, 골드와 함께 보여줍니다. 하나를 고르면 받는 사람 칸이 채워집니다."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "우편함 보내기 탭 옆의 첨부 버튼: 모든 직업용품, 한 종류의 직업용품, 또는 귀속되지 않은 장비를 한 번에 첨부합니다."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "게임이 숨기는 ID: 줄 숨기기는 툴팁에서 빼고, 숨김 표시는 숫자 대신 숨김으로 줄을 표시합니다."
