L["Drag the corner"] = "모서리 드래그"
L["Drag the corner to resize. Wheel: row height (Shift: spacing, Ctrl: text). Right-click a row for what it shows. Click the name or status line to change them."] = "모서리를 드래그해 크기를 조절합니다. 휠: 줄 높이 (Shift: 간격, Ctrl: 텍스트). 줄을 오른쪽 클릭하면 표시 내용을 고릅니다. 이름이나 상태 줄을 클릭해 변경하세요."
L["Drag the icon to a bar"] = "아이콘을 단축바로 드래그"
L["Drag the right edge"] = "오른쪽 가장자리 드래그"
L["Drag the right edge for width, a line's bottom for height. Wheel: text size (Shift: spacing, Ctrl: lines). Right-click a line for what it shows."] = "오른쪽 가장자리로 너비, 줄 아래쪽으로 높이를 조절합니다. 휠: 텍스트 크기 (Shift: 간격, Ctrl: 줄 수). 줄을 오른쪽 클릭하면 표시 내용을 고릅니다."
L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "오른쪽 가장자리로 너비를 조절합니다. 휠: 텍스트 크기 (Shift: 높이). 보너스나 시간을 클릭해 표시하거나 숨깁니다. 오른쪽 클릭으로 더 보기."
L["Drag to make the map bigger or smaller.\nRight-click: back to 100%."] = "드래그해 지도 크기를 조절합니다.\n오른쪽 클릭: 100%로 복원."
L["Drag to move it, right-click to take it off."] = "드래그해 옮기고, 오른쪽 클릭으로 뺍니다."
L["Drag to move, x to remove, + to add."] = "드래그로 이동, x로 제거, +로 추가."
L["Drag to move. Click x to remove."] = "드래그로 이동. x를 클릭해 제거."
L["Drag to place it."] = "드래그해 배치하세요."
L["Drag to resize. Turn off Lock Window first; resizing is available outside combat."] = "드래그해 크기를 조절합니다. 먼저 창 잠금을 끄세요. 크기 조절은 전투 중이 아닐 때 가능합니다."
L["Drag to turn"] = "드래그로 회전"
L["Drag up or down to change the gap between your aura and the class buttons."] = "위아래로 드래그해 오라와 직업 버튼 사이 간격을 바꿉니다."
