L["Every paladin in your group running Naowh Forever, and the blessing they give each class. Click an icon to change it: your own row always, anyone's while you lead the group or are an assistant. Only what that paladin has learned is offered, and changes reach them straight away."] = "Naowh Forever를 사용하는 파티의 모든 성기사와 직업별로 거는 축복. 아이콘을 클릭해 변경: 내 줄은 항상, 파티장이나 부공대장이면 누구든. 해당 성기사가 배운 축복만 제시되며 변경 사항은 바로 전달됩니다."
L["Every pick"] = "모든 선택"
