L["Every row is off: nothing shows."] = "모든 줄이 꺼져 있음: 아무것도 표시되지 않습니다."
L["Every setting now follows %s. Reload now to finish?"] = "이제 모든 설정이 %s(을)를 따릅니다. 지금 재시작해 마무리할까요?"
L["Every slot."] = "모든 칸."
L["every spell on your bars is at its highest rank."] = "단축바의 모든 주문이 최고 등급입니다."
L["every step done"] = "모든 단계 완료"
L["Every window looks like this."] = "모든 창이 이렇게 보입니다."
L["everyone"] = "모두"
L["Everyone in your party or raid: their Naowh Score, gear, talents and stats."] = "파티 또는 공격대 전원의 Naowh 점수, 장비, 특성, 능력치."
L["Everyone inspected"] = "전원 살펴봄"
L["Everyone passed"] = "전원 포기"
L["Everyone wearing the Epic badge: you keep Naowh Forever going too."] = "영웅 배지를 단 모든 분: 여러분도 Naowh Forever를 지탱해 주고 있습니다."
L["Everyone wearing the Legendary badge: you keep Naowh Forever going."] = "전설 배지를 단 모든 분: 여러분이 Naowh Forever를 지탱해 주고 있습니다."
L["Everyone who shared a score with you."] = "나와 점수를 공유한 모든 사람."
L["Everyone's gear, with its item level and enchants on hover."] = "모두의 장비. 마우스를 올리면 아이템 레벨과 마법부여 표시."
L["Everyone's key stats."] = "모두의 주요 능력치."
L["Everyone's Naowh Score, gear, talents and stats, side by side."] = "모두의 Naowh 점수, 장비, 특성, 능력치를 나란히 표시."
L["Everyone's talent points per tree."] = "모두의 특성 트리별 포인트."
