L["Everything you loot pops up on screen with its icon, amount and value, stacking in your chosen direction and fading out. Hover a line for the item's tooltip. Move it in the HUD Editor."] = "획득한 모든 것이 아이콘, 수량, 가치와 함께 화면에 나타나 지정한 방향으로 쌓였다가 사라집니다. 줄에 마우스를 올리면 아이템 툴팁을 봅니다. HUD 편집기에서 옮기세요."
L["Everything you wear has the best enchant for your level."] = "착용한 모든 장비에 현재 레벨에 가장 좋은 마법부여가 있습니다."
