L["Open Tracker in Dungeons"] = "던전에서 추적기 열기"
L["Open Training Planner"] = "훈련 플래너 열기"
L["Open World"] = "야외"
L["opens "] = "열기: "
L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "다른 플레이어의 전문 기술 링크를 이 창에서 열어 제작을 주문합니다. 제조법을 고르고, 제작 횟수를 정하고, 가져갈 재료를 체크(또는 개수 입력)한 뒤 주문에 추가하세요. 오른쪽 주문에는 제작당 권장 팁이 있으며 바꿀 수 있습니다. 요청은 제작마다 수량, 내 재료, 팁을 담은 메시지를 보냅니다: 파티 중이면 파티 대화, 아니면 귓속말. 가격과 팁은 경매장 검색이 필요합니다."
L["Opens its settings and leaves the HUD Editor."] = "설정을 열고 HUD 편집기를 나갑니다."
L["Opens the Aim Trainer now, out of combat."] = "비전투 시 지금 조준 훈련을 엽니다."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "아이템 ID와 효과 주문 ID로 각 아이템을 추가하는 AuraBuffs 창을 엽니다."
L["Opens the Consumable Bar's settings."] = "소비용품 바 설정을 엽니다."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "예시 주문에 복사 카드를 엽니다. ID나 링크를 선택한 후 Ctrl+C를 누르세요."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "던전 도감의 퀘스트 추적기 설정을 엽니다."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "HUD 편집기를 엽니다: 바가 함께 움직일 다른 Naowh Forever 요소를 클릭하세요."
L["Opens the Library Books tracker's settings."] = "도서관 책 추적기 설정을 엽니다."
L["Opens the planner on its Builds tab."] = "플래너의 빌드 탭을 엽니다."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "야외에서 퀘스트 대상 던전의 퀘스트 추적기를 엽니다."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "내 퀘스트가 있는 던전에 들어가면 퀘스트 추적기를 엽니다."
L["Opens the quiz now, or closes it."] = "지금 퀴즈를 열거나 닫습니다."
L["Opens the Run Timer settings."] = "진행 타이머 설정을 엽니다."
L["Opens the Sleeping Bag tracker's settings."] = "침낭 추적기 설정을 엽니다."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "능력치 가중치 창을 엽니다: 내 전문화에서 각 능력치의 가치와 이에 따른 최고 향상 아이템."
L["Opens the window now, out of combat."] = "비전투 시 지금 창을 엽니다."
L["Optional"] = "선택 사항"
L["Options"] = "옵션"
L["Options for the whole addon, saved for this computer."] = "애드온 전체 옵션, 이 컴퓨터에 저장됩니다."
L["OPTIONS WINDOW"] = "옵션 창"
