L["Paladins only. The melee bars take the color of the seal you have up. In combat that is the last seal you cast until it runs out, as the game keeps your buffs from addons there; out of combat it is read from your buffs."] = "성기사 전용. 근접 바가 현재 문장의 색을 띱니다. 전투 중에는 게임이 애드온에 효과 정보를 숨기므로 마지막으로 시전한 문장이 끝날 때까지 사용하고, 비전투 시에는 강화 효과에서 읽습니다."
