L["Pins every book you still need on its zone's map, and your librarian while you carry books. Hover a pin for the exact spot; click it for a waypoint."] = "아직 필요한 모든 책을 해당 지역 지도에 핀으로 표시하고, 책을 가지고 있으면 사서도 표시합니다. 핀에 마우스를 올리면 정확한 위치를, 클릭하면 경유지를 설정합니다."
L["Pins it and opens the map"] = "핀 설정 후 지도 열기"
L["Pins it only"] = "핀만 설정"
L["Pins the mailboxes near you on the minimap."] = "근처 우편함을 미니맵에 표시합니다."
