L["Plays as your target leaves melee range."] = "대상이 근접 사거리를 벗어날 때 재생합니다."
L["Plays Drop Alert with your list's first BiS, as you set it: up for a roll, dropped, then yours."] = "목록의 첫 BiS로 설정대로 획득 경고를 재생합니다: 주사위 굴림, 획득, 내 것."
L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "생명력이 기준 아래로 떨어질 때마다 한 번 재생합니다. 전투 중 게임이 애드온에 생명력을 숨기면 비전투 시에만 재생합니다."
L["Plays once when your threat climbs past the threshold, and again only after it drops back below."] = "위협 수준이 기준을 넘으면 한 번 재생하고, 다시 아래로 떨어진 후에만 다시 재생합니다."
L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "아직 필요한 책의 범위 안에 들어오면 지도 핑을 재생하고 대화창에 책 이름을 표시합니다. 멀어졌다가 다시 오기 전까지 책마다 한 번."
L["Plays the map ping when a book is near."] = "책이 근처에 있으면 지도 핑을 재생합니다."
L["Plays the sound again this often while out of range. 0 plays it once."] = "사거리 밖에 있는 동안 이 간격으로 소리를 다시 재생합니다. 0이면 한 번만."
L["Plays the sound picked here."] = "여기서 고른 소리를 재생합니다."
L["Plays when it is time to refresh the camp."] = "야영을 갱신할 때가 되면 재생합니다."
L["Plays when the warning comes up, and flashes the game's icon on your taskbar."] = "경고가 뜰 때 재생하고 작업 표시줄의 게임 아이콘을 깜빡입니다."
