L["Pops up when you enter a zone with books you still need, with a waypoint for each and your progress toward the next reward, and stays while you are in that zone. The X closes it until you enter another. Move it in the HUD Editor."] = "아직 필요한 책이 있는 지역에 들어가면 책마다 경유지와 다음 보상까지 진행도를 보여주는 창이 뜨고, 그 지역에 있는 동안 유지됩니다. X를 누르면 다른 지역에 들어갈 때까지 닫힙니다. HUD 편집기에서 옮기세요."
L["Popup Position"] = "팝업 위치"
