L["Press something still on cooldown and its icon, name and time left show by your mouse."] = "재사용 대기 중인 것을 누르면 마우스 옆에 아이콘, 이름, 남은 시간을 표시합니다."
L["Press this key to open Group Inspect, and again to close it."] = "이 키를 누르면 파티 살펴보기를 열고, 다시 누르면 닫습니다."
L["Press this key to open the BiS List, and again to close it."] = "이 키를 누르면 BiS 목록을 열고, 다시 누르면 닫습니다."
