L["Preview on: you wear no badge until you reload, as a player without one sees it."] = "미리보기 켜짐: 재시작할 때까지 배지가 없는 플레이어가 보는 것처럼 배지를 달지 않습니다."
L["Preview on: your name wears the %s badge until you reload. Say something to see it."] = "미리보기 켜짐: 재시작할 때까지 이름에 %s 배지를 답니다. 무언가 말해서 확인하세요."
