L["Protect Needed Items"] = "필요한 아이템 보호"
L["Pulling Aggro"] = "어그로 획득"
L["Pulsing Targets"] = "맥동하는 대상"
L["Put back every setting this page has changed?"] = "이 페이지에서 변경한 모든 설정을 되돌릴까요?"
L["put down what you are holding first."] = "먼저 들고 있는 것을 내려놓으세요."
L["Put every %s weight back to the defaults?"] = "모든 %s 가중치를 기본값으로 되돌릴까요?"
L["Put every setting back to how it was before the onboarding?"] = "모든 설정을 설정 안내 이전 상태로 되돌릴까요?"
L["Put every setting in this profile back to its default."] = "이 프로필의 모든 설정을 기본값으로 되돌립니다."
L["Put on in cities and inns, and taken off again when you leave."] = "도시와 여관에서 착용하고, 떠나면 다시 벗습니다."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "탈것을 타는 동안 착용하고, 내리면 이전 세트로 돌아갑니다."
L["Put the XP Bar colors back to their defaults?"] = "경험치 바 색상을 기본값으로 되돌릴까요?"
L["Put the XP Bar's size and texts back to their defaults?"] = "경험치 바 크기와 텍스트를 기본값으로 되돌릴까요?"
L["Put this bar back in"] = "이 바 다시 포함"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "주시 대상에 공격대 징표를 붙입니다. 같은 주시 대상에 매크로를 다시 누르면 징표를 지웁니다."
L["Puts back every setting this page has changed, to the value you had before."] = "이 페이지에서 변경한 모든 설정을 이전 값으로 되돌립니다."
L["Puts back everything changed since the HUD Editor opened."] = "HUD 편집기를 연 후 변경한 모든 것을 되돌립니다."
L["Puts back the last change. Ctrl + Z."] = "마지막 변경을 되돌립니다. Ctrl + Z."
L["Puts both back where the game shows them."] = "둘 다 게임이 표시하는 위치로 되돌립니다."
L["Puts every weight of this spec back to the defaults. Asks first."] = "이 전문화의 모든 가중치를 기본값으로 되돌립니다. 먼저 확인합니다."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "나보다 10레벨 이상 낮은 음식, 음료, 물약을 시계 표시와 함께 앞에 둡니다."
L["Puts the bar back on the screen."] = "바를 화면에 되돌립니다."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "바의 버튼을 원래대로 되돌립니다: 왼쪽에 던전 도감과 발견, 오른쪽에 BiS 목록과 훈련 플래너."
L["Puts the card back above the middle of the screen, where it starts."] = "카드를 처음 위치인 화면 가운데 위로 되돌립니다."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "최저가 아이템을 기준점 옆이 아닌 줄의 맨 끝에 둡니다."
L["Puts the cheapest item on your cursor, to drop or sell."] = "최저가 아이템을 커서에 집어 버리거나 팔 수 있게 합니다."
L["Puts the count just past the icon's edge."] = "개수를 아이콘 가장자리 바로 바깥에 둡니다."
L["Puts the key just past the icon's edge."] = "단축키를 아이콘 가장자리 바로 바깥에 둡니다."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "가방 내용과 관계없이 지정 횟수 제작분의 재료를 구매 목록에 넣습니다: 상인이 팔지 않는 체크된 재료 전부. 제외할 재료는 체크를 해제하세요. 경매장에서는 목록이 옆에 표시되어 가격을 확인하고 모두 구매할 수 있습니다."
L["Puts the popup back where it first showed."] = "팝업을 처음 표시된 위치로 되돌립니다."
L["Puts the quiz back where it first opened."] = "퀴즈를 처음 열린 위치로 되돌립니다."
