L["Shown: click to hide it."] = "표시됨: 클릭하면 숨깁니다."
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "던전 안에 있는 동안 세계 지도 옆에 우두머리와 전리품을 표시합니다."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "생명력이 기준 아래로 떨어지는 순간 치유 아이템 아이콘을 표시합니다 (전투 중 포함, 게임이 직접 표시하고 숨김). HUD 편집기에서 옮기세요."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "설정대로 그린 줄이 있는 예시 주문 툴팁을 표시합니다."
L["Shows a zone's level range when you hover it on the world map."] = "세계 지도에서 지역에 마우스를 올리면 레벨 범위를 표시합니다."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "약초 찾기, 광물 찾기, 물고기 찾기를 알지만 아무것도 추적하지 않을 때 화면에 아이콘을 표시합니다. 클릭해 추적 시작: 왼쪽 클릭은 첫 번째, 오른쪽 클릭은 두 번째, 휠 클릭은 세 번째. 마우스를 올리면 어떤 것인지 봅니다. 전투 중 숨김. HUD 편집기에서 옮기세요."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "침낭의 각 단계와 다음 단계로 가는 방법, 경유지를 표시합니다."
L["Shows every bonus again; click one on the preview to hide it."] = "모든 보너스를 다시 표시합니다. 미리보기에서 클릭하면 숨깁니다."
L["Shows how many of each you carry."] = "각각 몇 개 가지고 있는지 표시합니다."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "다른 캐릭터보다 앞서는지 뒤처지는지 표시하고 지난 레벨을 그에 따라 색칠합니다."
L["Shows it again a little before its effect runs out."] = "효과가 끝나기 조금 전에 다시 표시합니다."
L["Shows only part of the raid."] = "공격대 일부만 표시합니다."
L["Shows or hides the list of every element."] = "모든 요소 목록을 표시하거나 숨깁니다."
L["Shows the factions earned where you are beside the world map."] = "세계 지도 옆에 현재 위치에서 얻는 진영을 표시합니다."
L["Shows the key that uses each button."] = "각 버튼을 사용하는 단축키를 표시합니다."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "화면의 미터기 위치에 예시 바를 10초 동안 표시합니다. 비전투 시에만."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "전투 중에도 다른 방어 전담의 생명력 바 옆에 약화 효과를 표시합니다: 방어 전담 파괴 중첩, 우두머리 약화 효과, 내가 해제할 수 있는 모든 것."
L["Shows the parts of the world map you have not explored yet, darkened."] = "세계 지도에서 아직 탐험하지 않은 부분을 어둡게 표시합니다."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "가방이 이만큼 찼을 때만 줄을 표시합니다. 0이면 항상 표시합니다."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "아직 남은 침낭 단계를 지도에 표시합니다. 클릭하면 경유지를 설정합니다."
L["Shows the warning with its sound, about your target if you can attack it."] = "공격할 수 있는 대상이면 소리와 함께 경고를 표시합니다."
L["Shows this bonus on the bar: %s."] = "이 보너스를 바에 표시: %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "이 제조법의 재료를 보유 개수와 함께 목표 추적기에 표시합니다."
L["Shows this visit's time, coins, and experience."] = "이번 방문의 시간, 골드, 경험치를 표시합니다."
L["Shows up once you take the talent"] = "특성을 찍으면 표시됩니다"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "Naowh, 개발자, 운영진, 전설 및 영웅 후원자를 표시합니다: 대화창 이름 옆 배지, 툴팁 한 줄, 원하면 파티에 합류할 때 배너."
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "Naowh Forever로 나를 살펴보는 플레이어에게 내 BiS 별을 보여줍니다."
L["Shows your note and tag on a player's tooltip."] = "플레이어 툴팁에 내 메모와 태그를 표시합니다."
L["Shows your other characters' visits."] = "다른 캐릭터의 방문을 표시합니다."
