L["What a point of each stat is worth to your spec."] = "내 전문화에서 각 능력치 1포인트의 가치."
L["What a waypoint from the Discovery window or the tracker does."] = "발견 창이나 추적기의 경유지 동작."
L["What a zone's page in the Quest List window lists."] = "퀘스트 목록 창의 지역 페이지에 표시할 것."
L["What a zone's page in the Quest List window lists. Kills count from when Discovery is on: Shift-click a rare there to tick off one you killed before."] = "퀘스트 목록 창의 지역 페이지에 표시할 것. 처치는 발견을 켠 시점부터 집계됩니다: 이전에 처치한 희귀 몬스터는 거기서 Shift+클릭해 체크하세요."
L["What changed in recent builds."] = "최근 빌드의 변경 사항."
L["WHAT COMES ACROSS"] = "포함되는 것"
L["What drops in every dungeon and raid."] = "모든 던전과 공격대의 전리품."
L["What each line is worth, in gold, silver and copper."] = "각 줄의 가치 (골드, 실버, 코퍼)."
L["What each stack is worth, in its largest coin, under its icon."] = "각 묶음의 가치를 가장 큰 화폐 단위로 아이콘 아래에 표시."
L["What each stat is worth to your spec: change them as you like."] = "내 전문화에서 각 능력치의 가치: 원하는 대로 바꾸세요."
L["What each stat is worth to your spec: the BiS List's upgrade percents and enchants come from them. Change the weights in the Stat Weights window, from the scales on the BiS List's title bar."] = "내 전문화에서 각 능력치의 가치: BiS 목록의 향상 비율과 마법부여가 여기서 나옵니다. BiS 목록 제목 바의 저울 아이콘으로 여는 능력치 가중치 창에서 바꾸세요."
L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "내 전문화에서 각 능력치의 가치: 향상 비율과 마법부여가 여기서 나옵니다. 직접 정하세요."
L["What Happened"] = "일어난 일"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "상인을 열 때 할 동작. 둘 다 보충 알림 여부와 관계없이 작동합니다."
L["What It Lists"] = "표시 항목"
L["What it lists"] = "표시 항목"
L["What it puts on you: a buff, or an enchant on a weapon."] = "걸어주는 것: 강화 효과 또는 무기 마법부여."
L["What it says while you are in stealth."] = "은신 중일 때 표시할 문구."
L["What it says while you are out of stealth."] = "은신하지 않았을 때 표시할 문구."
L["What it shows as you enter combat."] = "전투에 들어갈 때 표시할 것."
L["What it shows as you leave combat."] = "전투에서 나올 때 표시할 것."
L["What Lines Show"] = "줄 표시 내용"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Naowh 전문 기술 창이 각 제조법에 추가하는 것: 아직 배우지 않은 제조법, 다음 등급, 각 재료 보유 개수."
L["What Rows Show"] = "줄 표시 내용"
L["What shows while you know a find but track none."] = "찾기 기술을 알지만 아무것도 추적하지 않을 때 표시할 것."
L["What the copy card has selected when it opens."] = "복사 카드가 열릴 때 선택된 항목."
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "도감이 우두머리에 표시할 것. 제목 바의 필터 아이콘과 같은 스위치입니다."
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "마지막 가격 검색이나 TradeSkillMaster 기준 묶음의 경매장 가격."
L["What the whole stack sells for at a vendor, and each item's price."] = "묶음 전체의 상점 판매가와 아이템별 가격."
L["What to train at each level, and its cost."] = "레벨별로 배울 것과 비용."
L["What you can train now and what each level brings."] = "지금 배울 수 있는 것과 레벨별로 얻는 것."
L["What you can train now, what each level brings and what it costs."] = "지금 배울 수 있는 것, 레벨별로 얻는 것과 비용."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "이 제작에 대해 제작자에게 줄 금액으로, 귓속말과 함께 보냅니다. 권장 팁으로 채워지며, 2g 50s, 75s, 2.5(골드)처럼 직접 입력하세요. 비우면 권장 금액으로 돌아갑니다."
L["What you wear that takes a better enchant for your level."] = "현재 레벨에 더 좋은 마법부여가 가능한 착용 장비."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "전투 중 대상의 상태: 짧은 강화 효과와 걸린 군중 제어."
L["Wheel"] = "휠"
L["Wheel on the rows"] = "줄 위에서 휠"
L["Wheel: size. Right-click for more."] = "휠: 크기. 오른쪽 클릭으로 더 보기."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "휠: 텍스트 크기. 줄을 클릭하면 숨깁니다. 오른쪽 클릭으로 더 보기."
L["When"] = "시점"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "전문 기술 숙련도가 다음 등급(숙련공, 전문가, 장인)에 도달하면 숙련도 바 아래와 개요의 카드에 필요한 것과 가르치는 사람을 배너로 표시합니다: 가장 가까운 전문가, 책 상인, 퀘스트 제공자. 경유지를 클릭하면 지도에 표시합니다. 도달하면 대화창에도 한 번 알리며, /naowh profrank로 다시 볼 수 있습니다."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "목록의 아이템이 주사위 굴림 중이거나 전리품 창에 있을 때, 그리고 내 것이 되었을 때. 화면 경고는 HUD 편집기에서 옮기세요."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "NPC가 여러 선택지를 줄 때 반납할 완료 퀘스트나 첫 번째 제안 퀘스트로 바로 갑니다. 위 두 옵션과 함께 작동합니다."
L["When it is up for a roll or drops."] = "주사위 굴림 중이거나 획득될 때."
L["When it is yours."] = "내 것이 되었을 때."
L["When You Leave"] = "나갈 때"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "배울 새 주문이 있는 레벨업 시 개수와 비용을 알리며, 플래너를 열거나 가장 가까운 전문가로 경유지를 설정하는 버튼이 있습니다. HUD 편집기에서 옮기세요."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "로그아웃할 때 이 캐릭터가 마지막으로 저장한 세트를 현재 단축바, 매크로, 단축키로 다시 저장합니다."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "도시나 여관에 도착하면 화면 가운데에 부족한 것을 깜빡이는 목록으로 표시합니다. 필요한 것을 갖추거나 떠날 때까지 유지됩니다. HUD 편집기에서 옮기세요."
L["When You Reset"] = "초기화할 때"
L["Where"] = "위치"
L["Where %s starts is not known."] = "%s의 시작 위치를 알 수 없습니다."
L["Where do you want to start?"] = "어디서 시작할까요?"
L["Where it comes from is not recorded yet; try the Auction House."] = "출처가 아직 기록되지 않았습니다. 경매장을 이용해 보세요."
L["Where It Drops"] = "획득처"
L["Where on the frame the bar sits."] = "프레임에서 바가 놓일 위치."
L["Where to get them"] = "얻는 곳"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "어그로까지 남은 거리와 항목 수 위치: 바 아래, 또는 제목 바와 바 사이."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "별 위치: 아이콘 모서리, 이름 앞, 또는 숨김."
L["Where? on Whispers"] = "귓속말에 어디?"
L["Whether a healthstone or a potion comes first."] = "생명석과 물약 중 무엇을 먼저 쓸지."
L["Whether a new mark counts on every character or only this one."] = "새 표시가 모든 캐릭터에 적용될지 이 캐릭터에만 적용될지."
L["Whether NF Food leaves drinks to NF Drink."] = "NF Food가 음료를 NF Drink에 맡길지 여부."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "능력별로 표시할 군중 제어: 모든 등급, 아이템과 생물의 같은 주문 포함."
L["Which debuffs show beside crowd control: off until you light them."] = "군중 제어 옆에 표시할 약화 효과: 켜기 전까지 꺼짐."
L["Which guild and title lines show with players' names, saved by the game itself."] = "플레이어 이름과 함께 표시할 길드 및 칭호 줄. 게임 자체에 저장됩니다."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "가방 검색이 추가하고 추가 묻기가 묻는 소비용품 종류."
L["Which mana spells get the line."] = "이 줄을 표시할 마나 주문."
L["Which modules do you want?"] = "어떤 모듈을 원하시나요?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "경고할 선택: BiS만, 상위 2개, 또는 목록의 모든 선택."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "둘 다 가지고 있을 때 매크로가 먼저 쓸 것: 생명석 또는 치유 물약."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "상인이 열려 있으면 선택한 제조법 재료 아래 구매 버튼이 그 상인이 파는 체크된 재료(굵은 실, 약한 융해제 등)를 옆에 정한 제작 횟수만큼 한 번에 구매합니다. 총 비용은 버튼 옆에 표시되며, 구매에 마우스를 올리면 재료별로 봅니다."
L["While flying"] = "비행 중"
L["While flying and at the campfire"] = "비행 중 및 모닥불에서"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "영웅의 일격, 회전베기, 후려치기, 랩터의 일격이 대기 중이면 근접 바가 그 색과 이름을 띱니다."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "경매장이 열려 있으면 선택한 제조법 재료 아래 구매 버튼이 옆에 정한 제작 횟수만큼 상인이 팔지 않는 체크된 재료를 구매합니다. 각각 먼저 가격을 보여주고 확인을 클릭할 때만 구매합니다."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "경매장이 열려 있으면 선택한 제조법 이름 옆의 경매장 검색 버튼이 제조법으로 만드는 아이템을 검색합니다. 배우지 않은 제조법에는 이를 가르치는 도안, 설계도, 교본을 찾는 제조법 검색도 있습니다. 마법부여처럼 아이템을 만들지 않는 제조법에는 경매장 검색이 없습니다."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "경매장이 열려 있으면 제조법이나 재료를 Shift+클릭해 해당 아이템(제조법 결과물 또는 재료)을 경매장에서 검색합니다. 대화 입력 중에는 Shift+클릭이 여전히 링크합니다."
L["While the mouse is away, with Show On Mouseover on."] = "마우스 오버 시 표시가 켜진 상태에서 마우스가 떨어져 있을 때."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "파티 중일 때 NPC에게서 수락한 퀘스트를 공유할 수 있으면 다른 파티원에게 공유합니다. 다른 사람이 공유해 준 퀘스트는 다시 공유하지 않습니다. 수락할 때 보조 키를 누르면 공유하지 않습니다."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "책을 가지고 있으면 받는 사람(사서 또는 마법사 전문가)에게 핀을 표시합니다."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "시전 중 주장비 바에 시전이 끝나는 지점을 표시합니다. 공격 시점이 됐는데도 시전이 계속되면 빨간색이 됩니다."
