L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "최대 숙련도는 %d입니다.\n먼저 퀘스트 %s%s|r(을)를 완료하세요 (%s숙련도 %d):"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "최대 숙련도는 %d입니다.\n먼저 %s(을)를 읽으세요 (숙련도 %d 필요):"
L["Your cap is %d.\nFirst train %s (%s, needs skill %d):"] = "최대 숙련도는 %d입니다.\n먼저 %s(을)를 배우세요 (%s, 숙련도 %d 필요):"
L["Your cast ends before the swing comes due."] = "공격 시점 전에 시전이 끝납니다."
L["Your cast will still be going as the swing comes due."] = "공격 시점에도 시전이 계속됩니다."
L["Your casts and channels swept around the ring too."] = "시전과 정신 집중도 링에 회전으로 표시."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "BiS 목록 스타일의 캐릭터 창(C): 칸별 표시, 내 전문화 능력치, 레벨 아래 Naowh 점수. 게임은 창과 모든 기능을 그대로 유지합니다. EllesmereUI 사용 시 이것을 켜면 재시작 후 그쪽 캐릭터 창이 꺼지고, 끄면 다시 켜집니다."
L["Your Characters"] = "내 캐릭터"
L["Your characters at level %d"] = "%d레벨의 내 캐릭터"
L["Your characters at level %d (%s)"] = "%d레벨의 내 캐릭터 (%s)"
L["Your characters on this realm and faction, remembered across your account: what they hold on item tooltips, and help at the mailbox."] = "계정 전체에서 기억하는 이 서버와 진영의 캐릭터: 아이템 툴팁의 보유 수량, 우편함 도우미."
