L["Counts the talents that raise a spell's healing or damage or give mana back, at the ranks you have."] = "주문의 치유량이나 피해량을 높이거나 마나를 돌려주는 특성을 현재 등급만큼 계산에 넣습니다."
L["Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer."] = "여러 개를 한 번에 제작하면(모두 생성 또는 수량을 지정한 생성) 비행 타이머처럼 생긴 바 하나로 전체 묶음을 표시합니다: 제조법, 완료한 수, 전체 남은 시간. 비행 중에는 아무도 제작하지 않으므로 비행 타이머 자리에 놓입니다: HUD 편집기에서 비행 타이머로 옮기세요."
L["Deathroll"] = "데스롤"
L["Deathroll in progress"] = "데스롤 진행 중"
