L["Default: the item you carry, or the kind's usual icon. Last Used: the icon of the food, flask, elixir, scroll or weapon item you used last."] = "기본값: 가지고 있는 아이템 또는 해당 종류의 기본 아이콘. 최근 사용: 마지막으로 사용한 음식, 영약, 비약, 두루마리, 무기 아이템의 아이콘."
L["Disenchant Next Item"] = "다음 아이템 마력 추출"
L["Or press %s for the next item."] = "또는 %s 키를 눌러 다음 아이템으로."
L["Set a key for this in Key Bindings, under Naowh Forever, or in the Disenchant Window settings."] = "단축키 > Naowh Forever 또는 마력 추출 창 설정에서 키를 지정하세요."
L["Disenchants the next item in the Disenchant window while it is open, one item per press, like a click on Disenchant All."] = "마력 추출 창이 열려 있는 동안 한 번 누를 때마다 다음 아이템 하나를 마력 추출합니다. 모두 마력 추출을 클릭한 것과 같습니다."
L["Drag to reorder within this section."] = "드래그하여 이 구역 안에서 순서를 바꿉니다."
L["Dresses the addon's windows as Naowh's own or WoW Forever's, after a reload."] = "재시작 후 애드온 창을 Naowh 스타일 또는 WoW Forever 스타일로 꾸밉니다."
