L["No weapon master is known for your faction."] = "내 진영의 무기 전문가를 알 수 없습니다."
L["Notches"] = "눈금"
L["Nothing marked. Ctrl-click an item in your bags to mark it."] = "표시된 것이 없습니다. 가방에서 아이템을 Ctrl+클릭해 표시하세요."
L["TURNED OFF"] = "꺼짐"
L["%s is turned off. Turn it on to change these settings."] = "%s(이)가 꺼져 있습니다. 이 설정을 바꾸려면 켜세요."
L["Off thanks every caster with the /thank emote instead; needs Thank With an Emote."] = "끄면 대신 /thank 감정 표현으로 모든 시전자에게 감사합니다. 감정 표현으로 감사하기가 필요합니다."
L["On: any flask, elixir or buff food in your bags reminds you, listed or not; off: even with none."] = "켬: 목록에 있든 없든 가방에 영약, 비약, 강화 음식이 있으면 알립니다. 끔: 하나도 없어도 알립니다."
L["Off: a reminder even with none in your bags, so you know to buy some."] = "끔: 가방에 하나도 없어도 알려서 살 때가 되었음을 알 수 있습니다."
L["Only %d of %d available; %s"] = "%2$d개 중 %1$d개만 구매 가능. %3$s"
L["Only the session host can start a new session."] = "세션 진행자만 새 세션을 시작할 수 있습니다."
L["Open a flight master's map to save the points you know"] = "알고 있는 비행 경로를 저장하려면 비행 조련사 지도를 여세요"
L["Open Discovery"] = "발견 열기"
L["Open Gamble"] = "도박 열기"
L["Opens the Gamble window."] = "도박 창을 엽니다."
L["Out in the world, with each reminder you show in the world."] = "야외에서, 야외에서 표시하는 각 알림과 함께."
L["Resume Scan"] = "검색 재개"
