L["Raid Buffs to Remind"] = "알릴 공격대 강화 효과"
L["Personal Buffs to Remind"] = "알릴 개인 강화 효과"
L["Pick a guide"] = "가이드 선택"
L["Pick a Spell Panel Color or a Window Color"] = "주문 패널 색상 또는 창 색상을 고르세요"
L["Pixel Glow runs lines around the icon; Standard Glow is the game's own button glow."] = "픽셀 빛은 아이콘 주위로 선이 돌고, 기본 빛은 게임 자체 버튼 빛입니다."
