L["Claim saved: your badge shows once this character is on the badge list, with the next Naowh Forever update."] = "수령 정보 저장됨: 다음 Naowh Forever 업데이트로 이 캐릭터가 배지 목록에 오르면 배지가 표시됩니다."
L["Your Naowh Forever badge needs claiming on this character: the Naowh Forever app does it for you, or type /nf badges claim with the code from your naowh.gg account."] = "이 캐릭터에서 Naowh Forever 배지를 수령해야 합니다: Naowh Forever 앱이 대신 처리하거나, naowh.gg 계정의 코드와 함께 /nf badges claim을 입력하세요."
L["Your Naowh Forever badge is off on this character: its claim, or the BattleTag saved on naowh.gg, is not this character's."] = "이 캐릭터에서 Naowh Forever 배지가 꺼져 있습니다: 수령 정보나 naowh.gg에 저장된 배틀태그가 이 캐릭터의 것이 아닙니다."
