L["The XP from a quest you hand in flashes on the bar and its amount rises off it."] = "반납한 퀘스트의 경험치가 바에서 번쩍이고 그 양이 바 위로 떠오릅니다."
L["These are Library macros. They are added as character macros on this character."] = "라이브러리 매크로입니다. 이 캐릭터의 캐릭터 전용 매크로로 추가됩니다."
