L["A .png, .tga or .blp file. Make its width and height powers of two, such as 128, 256, 512 or 1024, to be safe; a small one, 128 or 256, is good for a pattern that is repeated with Tile Image, and Tile Size says how wide each repeat is. A .jpg is most likely not read by the game: open it and save it as a .png first."] = ".png, .tga 또는 .blp 파일. 안전하게 너비와 높이를 128, 256, 512, 1024 같은 2의 거듭제곱으로 맞추세요. 이미지 바둑판으로 반복할 무늬에는 128이나 256 같은 작은 이미지가 좋으며, 바둑판 크기가 반복 하나의 너비를 정합니다. .jpg는 게임이 읽지 못할 가능성이 높으니 먼저 열어서 .png로 저장하세요."
