L["The current fight, everything since the last reset, or a past fight."] = "현재 전투, 마지막 초기화 이후 전체, 또는 지난 전투."
L["The current fight, or everything since the last reset."] = "현재 전투 또는 마지막 초기화 이후 전체."
L["The damage meter is not available"] = "피해 미터기를 사용할 수 없음"
L["The fastest way anywhere: walking, flights, boats, zeppelins, the tram, portals and your Hearthstone."] = "어디든 가장 빠른 길: 도보, 비행, 배, 비행선, 지하철, 차원문, 귀환석."
L["The fights kept, when the game's figures are cleared, and the way back to the defaults."] = "보관할 전투, 게임 수치를 지우는 시점, 기본값으로 되돌리는 방법."
L["The fights kept: when, which, how long, and the per-second figures."] = "보관한 전투: 시점, 대상, 길이, 초당 수치."
L["The figures' color. Their size, font and class colors are behind the cog."] = "수치의 색상. 크기, 글꼴, 직업 색상은 톱니바퀴 뒤에 있습니다."
L["The figures' size, font and color."] = "수치의 크기, 글꼴, 색상."
L["The first row at the bottom and the rest stacked above it, as some meters do."] = "일부 미터기처럼 첫 줄을 맨 아래에 두고 나머지를 위로 쌓습니다."
L["The game did not find the file. Check the folder name, the spelling and the extension, and that the game was restarted after the file was added."] = "게임이 파일을 찾지 못했습니다. 폴더 이름, 철자, 확장자를 확인하고 파일을 추가한 후 게임을 재시작했는지 확인하세요."
L["The game would not save the layout (%s)."] = "게임이 레이아웃을 저장하지 않았습니다 (%s)."
L["The game's layouts are not available."] = "게임 레이아웃을 사용할 수 없습니다."
L["The game's meter has no window to place."] = "게임 미터기에 배치할 창이 없습니다."
L["The game's own damage meter: in your theme, sized and set here instead of in Edit Mode."] = "게임 자체 피해 미터기: 내 테마로 표시하고, 편집 모드 대신 여기서 크기와 설정을 정합니다."
L["The game's own sparkle on every quest item, kept on through graphics presets; Glimmer's Effect does not change it."] = "모든 퀘스트 아이템에 게임 자체 반짝임을 표시하며, 그래픽 프리셋을 바꿔도 유지됩니다. Glimmer의 효과는 이것을 바꾸지 않습니다."
L["The game's own, in your Accent, or hidden; the mouse wheel still scrolls."] = "게임 기본, 강조색, 또는 숨김. 마우스 휠 스크롤은 그대로 작동합니다."
L["The game's own, none, the soft shadow, a thin outline or a thick one."] = "게임 기본, 없음, 부드러운 그림자, 얇은 외곽선 또는 두꺼운 외곽선."
L["The gap between the bars."] = "바 사이 간격."
L["The icon's size, style, side and crop."] = "아이콘의 크기, 스타일, 방향, 자르기."
L["The icon's size; zero fits it to the bar."] = "아이콘 크기. 0이면 바에 맞춥니다."
L["The list and session names in the title bar."] = "제목 바의 목록 및 세션 이름."
L["The list and the session, report, reset, add or close a window, and settings."] = "목록과 세션, 보고, 초기화, 창 추가 또는 닫기, 설정."
L["The list name in the title bar, 0 being the game's own size."] = "제목 바의 목록 이름. 0은 게임 기본 크기입니다."
L["The list the window shows."] = "창에 표시할 목록."
L["The list's name, the fight's name, or both."] = "목록 이름, 전투 이름, 또는 둘 다."
L["The names on the bars, 0 being the game's own size."] = "바의 이름. 0은 게임 기본 크기입니다."
L["The names on the bars."] = "바의 이름."
L["The names' color. How a name is written, and its size and font, are behind the cog."] = "이름 색상. 이름 표기 방식, 크기, 글꼴은 톱니바퀴 뒤에 있습니다."
L["The names' size, which the figures follow unless they have their own."] = "이름 크기. 수치에 별도 크기가 없으면 이를 따릅니다."
L["The panel a left click opens, the Window Color until you pick one."] = "왼쪽 클릭으로 여는 패널. 고르기 전까지는 창 색상입니다."
L["The path of your own picture."] = "내 그림의 경로."
L["The picture"] = "그림"
L["The raid's figure per second, once the fight is over."] = "전투가 끝난 후 공격대의 초당 수치."
L["The rank's size, font and color."] = "순위의 크기, 글꼴, 색상."
L["The room at the ends of a row, before the first text and after the last."] = "줄 양 끝, 첫 텍스트 앞과 마지막 텍스트 뒤의 여백."
L["The room between the columns of figures."] = "수치 열 사이 간격."
L["The room between the icon and the name."] = "아이콘과 이름 사이 간격."
L["The session button and the ... menu at the bar's right end."] = "바 오른쪽 끝의 세션 버튼과 ... 메뉴."
L["The size of all the text, against normal."] = "기본 대비 모든 텍스트의 크기."
L["The spells behind a row, on hover or in the window, and what Report To sends."] = "마우스 오버나 창에서 보는 줄의 주문 상세와 보고 대상으로 보내는 내용."
L["The strip on the left of a row, which shows your row in your edge color."] = "줄 왼쪽의 띠. 내 줄을 가장자리 색상으로 표시합니다."
L["The strip on the left of your row when Your Row Edge is Custom Color."] = "내 줄 가장자리가 사용자 설정 색상일 때 내 줄 왼쪽의 띠."
L["The strip on the left of your row: the theme's Accent, your class's color, or one of your own."] = "내 줄 왼쪽의 띠: 테마 강조색, 직업 색상 또는 직접 고른 색."
L["The title bar's buttons: the game's own, or in your theme."] = "제목 바 버튼: 게임 기본 또는 내 테마."
L["The title bar."] = "제목 바."
L["The title's color. Its size, font and place are behind the cog."] = "제목 색상. 크기, 글꼴, 위치는 톱니바퀴 뒤에 있습니다."
L["The title's size, font, color and place."] = "제목의 크기, 글꼴, 색상, 위치."
L["The title, the fight time and the buttons, and the column titles and summary line under the bar."] = "제목, 전투 시간, 버튼, 그리고 바 아래의 열 제목과 요약 줄."
L["The window and the shadow behind each bar."] = "창과 각 바 뒤의 그림자."
