L["What each row has before its figures: icon, rank and name, each with its settings behind its cog."] = "각 줄에서 수치 앞에 오는 것: 아이콘, 순위, 이름. 각각의 설정은 톱니바퀴 뒤에 있습니다."
L["What it shows in a row."] = "한 줄에 표시할 내용."
L["What the fade does with the mouse."] = "마우스에 따른 흐려짐 동작."
L["What the line says, and its size, font and color."] = "줄에 표시할 내용과 크기, 글꼴, 색상."
L["What the mouse does while the window is locked."] = "창이 잠겨 있는 동안 마우스의 동작."
L["What the window lists, for which session, and when it shows."] = "창에 나열할 항목, 세션, 표시 시점."
L["What to do in the settings"] = "설정에서 할 일"
L["What you are short on when you reach a city or inn."] = "도시나 여관에 도착했을 때 부족한 것."
L["When the meter shows: always, in combat, in a group or never."] = "미터기 표시 시점: 항상, 전투 중, 파티 중, 표시 안 함."
L["When the window shows: always, or only in a place or in combat."] = "창 표시 시점: 항상, 또는 특정 장소나 전투 중에만."
L["When you are not among the rows shown, the last row is yours, with your rank."] = "표시된 줄에 내가 없으면 마지막 줄에 내 순위와 함께 나를 표시합니다."
L["Where it goes"] = "넣을 위치"
L["Where the time sits, and its size, font and color."] = "시간의 위치와 크기, 글꼴, 색상."
L["Whether the biggest bar or the list's total is a full bar."] = "가장 큰 바와 목록 합계 중 무엇을 꽉 찬 바로 할지."
L["Which column stands where, left to right, in each row: the name, the total, the per-second figure, the share, or another list's total for the same player. Another list's total fills in after the fight."] = "각 줄에서 왼쪽부터 오른쪽으로 놓일 열: 이름, 합계, 초당 수치, 비율, 또는 같은 플레이어의 다른 목록 합계. 다른 목록의 합계는 전투 후에 채워집니다."
L["Which columns a row has and where, and how numbers, shares and per-second figures are written."] = "줄에 들어갈 열과 위치, 숫자, 비율, 초당 수치의 표기 방식."
L["Window Background"] = "창 배경"
L["Window Border"] = "창 테두리"
L["Window Position"] = "창 위치"
L["Window Width"] = "창 너비"
L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep that one copy, or Shift-right-click to keep every copy of it, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "마법부여 창을 열면 위쪽의 마력 추출 버튼이 가방에서 마력 추출할 수 있는 모든 아이템(녹색, 파란색, 보라색 무기와 방어구)을 보여주는 창을 엽니다 (또는 /naowh disenchant 입력). 아이템을 오른쪽 클릭하면 그 하나를, Shift+오른쪽 클릭하면 모든 사본을 모든 캐릭터에서 다시 오른쪽 클릭할 때까지 보관합니다. 게임이 마력 추출마다 클릭을 요구하므로, 모두 마력 추출은 클릭할 때마다 나머지를 하나씩 마력 추출합니다. 게임이 받지 않는 아이템(숙련도 부족)은 재시작할 때까지 건너뜁니다. 전투가 시작되면 닫힙니다."
L["Writes the per-second figure with /s after it."] = "초당 수치 뒤에 /s를 붙입니다."
L["Writes the time as (0:05)."] = "시간을 (0:05)처럼 표기합니다."
L["Writes the total and the per-second figure as one text with a bar between: 117 | 23."] = "합계와 초당 수치를 막대로 구분한 한 텍스트로 표기합니다: 117 | 23."
L["Writing"] = "표기"
L["You entered a new instance. Reset the damage meter data?"] = "새 인스턴스에 입장했습니다. 피해 미터기 데이터를 초기화하시겠습니까?"
L["You have no Battle.net friends."] = "Battle.net 친구가 없습니다."
L["Your active layout is one of the game's own: make a copy in Edit Mode first."] = "현재 레이아웃은 게임 기본 레이아웃입니다: 먼저 편집 모드에서 사본을 만드세요."
L["Your Bar"] = "내 바"
L["Your Bar Color"] = "내 바 색상"
L["Your bar's color, and the strip on the left of your row."] = "내 바의 색상과 내 줄 왼쪽의 띠."
L["Your group is full."] = "파티가 가득 찼습니다."
L["Your own bar: the same as the others, in your class's color, or in a color of its own."] = "내 바: 다른 바와 같게, 직업 색상으로, 또는 별도 색상으로."
L["Your Own Picture"] = "내 그림"
L["Your own picture's path, and how the picture is drawn."] = "내 그림의 경로와 그림을 그리는 방식."
L["Your own row says You in place of your name."] = "내 줄에 내 이름 대신 '나'를 표시합니다."
L["Your Row"] = "내 줄"
L["Your Row Edge"] = "내 줄 가장자리"
