L["Reminds you about your equipped ammo at its own amount, not the carry target."] = "휴대 목표가 아닌 별도 수량을 기준으로 장착한 탄약을 알립니다."
L["Reminds at or below this many equipped arrows or shot across all bag stacks."] = "모든 가방의 장착 화살이나 탄환이 이 수량 이하가 되면 알립니다."
L["%s changes the same game settings as Glimmer, so they undo each other. Disable %s?"] = "%s(은)는 Glimmer와 같은 게임 설정을 바꾸므로 서로 설정을 되돌립니다. %s(을)를 비활성화할까요?"
