L["Add an item ID, drag an item onto its section, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "아이템 ID를 추가하거나, 아이템을 해당 구역으로 드래그하거나, 목록을 가져오세요. 음식은 포만감 효과를, 다른 아이템은 자체 효과를 확인합니다. 다른 효과를 주는 아이템에만 효과 주문 ID를 추가하세요. 자동으로 추가되는 것은 없습니다. 알림에 마우스를 올려 가방에서 설정된 아이템을 고르세요. 알림은 전투 중 멈추며, 아이템 메뉴는 전투 밖에서 작동합니다. 표시 시점과 위치는 AuraBuffs > 설정에 있습니다."
